//! Config loader for `viewer-ctl.toml` (ported from viewer-ctl).
//!
//! All paths in the file are relative to the repo root, which install-ctl
//! resolves via `registry::resolve_repo_root` (see that module's doc
//! comment for why the two resolvers were unified onto one root).
//!
//! See `viewer-ctl.toml` at the repo root for the schema and live data.

use std::{
    fs,
    path::{
        Path,
        PathBuf,
    },
};

use serde::Deserialize;

// ── Top-level ────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct Config {
    #[serde(default)]
    pub defaults: Defaults,
    #[serde(default, rename = "server")]
    pub servers: Vec<Server>,
    #[serde(default, rename = "frontend")]
    pub frontends: Vec<Frontend>,
    #[serde(default, rename = "extension")]
    pub extensions: Vec<Extension>,
    #[serde(default, rename = "task")]
    pub tasks: Vec<Task>,
}

#[derive(Debug, Deserialize, Default)]
pub struct Defaults {
    /// Where installed frontend bundles live.  Supports a leading `~`.
    #[serde(default = "default_install_root")]
    pub frontend_install_root: String,
}

#[allow(dead_code)]
fn default_install_root() -> String {
    "~/.context-engine/static".to_string()
}

// ── Component types ──────────────────────────────────────────────────────────

#[derive(Debug, Deserialize, Clone)]
pub struct Server {
    pub name: String,
    pub package: String,
    pub port: u16,
    pub source_dir: String,
    #[serde(default)]
    pub start_args: Vec<String>,
    #[serde(default)]
    pub env: std::collections::BTreeMap<String, String>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct Frontend {
    pub name: String,
    /// Name of the [[server]] this frontend is served by, used to derive the
    /// `STATIC_DIR` env var passed to the server at start time.
    #[serde(default)]
    pub serves: Option<String>,
    pub source_dir: String,
    pub build_cmd: Vec<String>,
    pub build_output: String,
    /// Additional directories whose contents are copied into the install
    /// dir after the build (e.g. `public/` assets that trunk skipped).
    #[serde(default)]
    pub extra_assets: Vec<String>,
    #[serde(default)]
    pub prebuild: Vec<PrebuildStep>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct PrebuildStep {
    pub dir: String,
    pub cmd: Vec<String>,
    /// Optional condition. Currently supported:
    ///   `missing:<relpath>`  → run only if `<dir>/<relpath>` does not exist.
    #[serde(default)]
    pub condition: Option<String>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct Extension {
    pub name: String,
    /// Built-in installer kind. Currently `"vscode"` is recognised.
    pub kind: String,
    pub source_dir: String,
    #[serde(default = "default_pkg_json")]
    pub package_json: String,
    pub build_cmd: Vec<String>,
}

#[allow(dead_code)]
fn default_pkg_json() -> String {
    "package.json".to_string()
}

#[derive(Debug, Deserialize, Clone)]
pub struct Task {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub steps: Vec<TaskStep>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct TaskStep {
    pub dir: String,
    pub cmd: Vec<String>,
    #[serde(default)]
    pub allow_failure: bool,
}

// ── Lookup helpers ───────────────────────────────────────────────────────────

/// Resolved component reference returned by [`Config::lookup`].
pub enum Component<'a> {
    Server(&'a Server),
    Frontend(&'a Frontend),
    Extension(&'a Extension),
}

impl Config {
    /// Load the config from `<repo_root>/viewer-ctl.toml`.
    pub fn load(repo_root: &Path) -> Result<Self, String> {
        let path = repo_root.join("viewer-ctl.toml");
        let text = fs::read_to_string(&path).map_err(|e| {
            format!("failed to read {}: {e}", crate::paths::disp(&path))
        })?;
        let cfg: Config = toml::from_str(&text).map_err(|e| {
            format!("failed to parse {}: {e}", crate::paths::disp(&path))
        })?;
        cfg.validate()?;
        Ok(cfg)
    }

    fn validate(&self) -> Result<(), String> {
        // Each frontend.serves must reference a known server.
        for fe in &self.frontends {
            if let Some(s) = &fe.serves
                && !self.servers.iter().any(|sv| &sv.name == s)
            {
                return Err(format!(
                    "frontend `{}` declares serves=`{s}` but no [[server]] with that name exists",
                    fe.name
                ));
            }
        }
        Ok(())
    }

    /// Find a component by name. Searches servers, then frontends, then
    /// extensions. Returns `None` if no match.  Components of different
    /// kinds may share a name (e.g. server + frontend with the same name);
    /// callers needing to disambiguate should use the typed accessors.
    #[allow(dead_code)]
    pub fn lookup(
        &self,
        name: &str,
    ) -> Option<Component<'_>> {
        if let Some(s) = self.server(name) {
            return Some(Component::Server(s));
        }
        if let Some(f) = self.frontend(name) {
            return Some(Component::Frontend(f));
        }
        if let Some(e) = self.extension(name) {
            return Some(Component::Extension(e));
        }
        None
    }

    pub fn server(
        &self,
        name: &str,
    ) -> Option<&Server> {
        self.servers.iter().find(|s| s.name == name)
    }

    pub fn frontend(
        &self,
        name: &str,
    ) -> Option<&Frontend> {
        self.frontends.iter().find(|f| f.name == name)
    }

    pub fn extension(
        &self,
        name: &str,
    ) -> Option<&Extension> {
        self.extensions.iter().find(|e| e.name == name)
    }

    pub fn task(
        &self,
        name: &str,
    ) -> Option<&Task> {
        self.tasks.iter().find(|t| t.name == name)
    }

    /// Find the frontend (if any) whose `serves` field links it to `server_name`.
    pub fn frontend_for_server(
        &self,
        server_name: &str,
    ) -> Option<&Frontend> {
        self.frontends
            .iter()
            .find(|f| f.serves.as_deref() == Some(server_name))
    }

    /// Resolve the install root for frontends, expanding `~`.
    pub fn frontend_install_root(&self) -> PathBuf {
        expand_tilde(&self.defaults.frontend_install_root)
    }

    /// Resolve the install dir for one specific frontend.
    pub fn frontend_install_dir(
        &self,
        frontend_name: &str,
    ) -> PathBuf {
        self.frontend_install_root().join(frontend_name)
    }
}

/// Expand a leading `~` to the user's home directory.
pub fn expand_tilde(path: &str) -> PathBuf {
    if let Some(stripped) =
        path.strip_prefix("~/").or_else(|| path.strip_prefix("~\\"))
        && let Some(home) = dirs::home_dir()
    {
        return home.join(stripped);
    }
    if path == "~"
        && let Some(home) = dirs::home_dir()
    {
        return home;
    }
    PathBuf::from(path)
}

//! Clap types for the viewer lifecycle subcommand surface (ported from
//! viewer-ctl's `cli.rs`). Nested under `install-ctl viewer <...>` — see
//! `main.rs` for the top-level surface and the list/install collision note.

use clap::{
    Subcommand,
    ValueEnum,
};

#[derive(Subcommand)]
pub enum ViewerCmd {
    /// List every component defined in viewer-ctl.toml.
    List,
    /// Show running state of one or all servers.
    Status { name: Option<String> },
    /// Build artifacts for a component (no install).
    Build {
        name: String,
        /// Restrict to a single component kind when the name is ambiguous.
        #[arg(long)]
        kind: Option<KindArg>,
    },
    /// Install built artifacts.
    /// - server     → cargo install --path <source_dir> --force
    /// - frontend   → copy build_output to <install_root>/<name>/
    /// - extension  → kind-specific (e.g. vscode sync)
    Install {
        name: String,
        #[arg(long)]
        kind: Option<KindArg>,
    },
    /// Start a server. Sets STATIC_DIR if a frontend is linked AND installed.
    Start {
        server: String,
        /// Keep the server in the foreground: inherit the current stdout/stderr
        /// and block until the process exits. By default the server is
        /// detached and viewer-ctl exits once the port is ready.
        #[arg(long, alias = "fg", short = 'f')]
        foreground: bool,
        /// Extra args forwarded to the server binary.
        #[arg(last = true)]
        extra: Vec<String>,
    },
    /// Stop the server (kills the process listening on its port).
    Stop { server: String },
    /// Stop then start the server.
    Restart {
        server: String,
        /// Keep the server in the foreground (see `start --foreground`).
        #[arg(long, alias = "fg", short = 'f')]
        foreground: bool,
        #[arg(last = true)]
        extra: Vec<String>,
    },
    /// Run a named task (sequence of shell commands).
    Task { name: String },
    /// Build + install the frontend linked to the given server.
    ///
    /// Designed for use as a vscode `preLaunchTask` so a debug launch of the
    /// server binary serves a freshly built frontend bundle. A no-op if the
    /// server has no linked frontend. Prints the resolved install dir to
    /// stdout so it can be captured for `STATIC_DIR`.
    Prepare { server: String },
    /// Print the resolved STATIC_DIR for a server's linked frontend.
    ///
    /// Exits with an error if no frontend is linked. Does not build or
    /// install — useful for scripting around the install layout.
    StaticDir { server: String },
}

#[derive(Clone, Copy, ValueEnum, Debug)]
pub enum KindArg {
    Server,
    Frontend,
    Extension,
}

//! Command implementations for the viewer lifecycle surface (ported from
//! viewer-ctl).
//!
//! - `list` / `status` — read-only inspection
//! - `build` / `install` — dispatched per component kind via [`for_matching`]
//! - `start` / `stop` / `restart` — see [`server`]
//! - `task` — see [`task`]

pub mod extension;
pub mod frontend;
pub mod server;
pub mod task;

use std::path::Path;

use crate::{
    cli::KindArg,
    config::{
        Component,
        Config,
    },
    paths::disp,
    process::{
        kill_process,
        pids_by_image_name,
        pids_on_port,
    },
};

use self::{
    extension::{
        build_extension,
        install_extension,
    },
    frontend::{
        build_frontend,
        install_frontend,
    },
    server::{
        build_server,
        install_server,
    },
};

pub use self::{
    server::{
        cmd_start,
        cmd_stop,
    },
    task::cmd_task,
};

// ── list / status ────────────────────────────────────────────────────────────

pub fn cmd_list(cfg: &Config) -> Result<(), String> {
    println!("servers:");
    for s in &cfg.servers {
        let fe = cfg
            .frontend_for_server(&s.name)
            .map(|f| format!(" ↔ frontend `{}`", f.name))
            .unwrap_or_default();
        println!(
            "  {:<16}  package={}  port={}{}",
            s.name, s.package, s.port, fe
        );
    }
    println!("frontends:");
    for f in &cfg.frontends {
        let install = cfg.frontend_install_dir(&f.name);
        println!(
            "  {:<16}  serves={:<14}  install={}",
            f.name,
            f.serves.as_deref().unwrap_or("-"),
            disp(&install)
        );
    }
    println!("extensions:");
    for e in &cfg.extensions {
        println!("  {:<16}  kind={}  source={}", e.name, e.kind, e.source_dir);
    }
    println!("tasks:");
    for t in &cfg.tasks {
        let desc = if t.description.is_empty() {
            String::new()
        } else {
            format!(" — {}", t.description)
        };
        println!("  {}{desc}", t.name);
    }
    Ok(())
}

pub fn cmd_status(
    cfg: &Config,
    name: Option<&str>,
) -> Result<(), String> {
    let servers: Vec<_> = match name {
        Some(n) => match cfg.server(n) {
            Some(s) => vec![s],
            None =>
                return Err(format!(
                    "no [[server]] named `{n}` in viewer-ctl.toml"
                )),
        },
        None => cfg.servers.iter().collect(),
    };
    for s in servers {
        let pids = pids_on_port(s.port);
        if pids.is_empty() {
            println!("  {:<16}  port={}  (down)", s.name, s.port);
        } else {
            let pid_list: Vec<String> =
                pids.iter().map(|p| p.as_u32().to_string()).collect();
            println!(
                "  {:<16}  port={}  pids=[{}]",
                s.name,
                s.port,
                pid_list.join(",")
            );
        }
    }
    Ok(())
}

// ── build / install dispatch ─────────────────────────────────────────────────

/// Apply a per-kind action to every component matching `name` in `cfg`.
///
/// When `kind` is `None` and multiple matches exist, all are processed in
/// the order: server, frontend, extension.
fn for_matching<F>(
    cfg: &Config,
    name: &str,
    kind: Option<KindArg>,
    mut action: F,
) -> Result<(), String>
where
    F: FnMut(Component<'_>) -> Result<(), String>,
{
    let mut matched = false;

    if matches!(kind, None | Some(KindArg::Server))
        && let Some(s) = cfg.server(name)
    {
        action(Component::Server(s))?;
        matched = true;
    }
    if matches!(kind, None | Some(KindArg::Frontend))
        && let Some(f) = cfg.frontend(name)
    {
        action(Component::Frontend(f))?;
        matched = true;
    }
    if matches!(kind, None | Some(KindArg::Extension))
        && let Some(e) = cfg.extension(name)
    {
        action(Component::Extension(e))?;
        matched = true;
    }

    if !matched {
        return Err(format!(
            "no component named `{name}` (kind filter: {:?}). Run `install-ctl viewer list`.",
            kind
        ));
    }
    Ok(())
}

pub fn cmd_build(
    cfg: &Config,
    root: &Path,
    name: &str,
    kind: Option<KindArg>,
) -> Result<(), String> {
    for_matching(cfg, name, kind, |c| match c {
        Component::Server(s) => build_server(root, s),
        Component::Frontend(f) => build_frontend(root, f),
        Component::Extension(e) => build_extension(root, e),
    })
}

pub fn cmd_install(
    cfg: &Config,
    root: &Path,
    name: &str,
    kind: Option<KindArg>,
) -> Result<(), String> {
    for_matching(cfg, name, kind, |c| match c {
        Component::Server(s) => install_server(root, s),
        Component::Frontend(f) => install_frontend(cfg, root, f),
        Component::Extension(e) => install_extension(cfg, root, e),
    })
}

// ── prepare / static-dir ─────────────────────────────────────────────────────

/// Build + install the frontend linked to `server_name` and print its
/// resolved install dir.
///
/// Intended as a vscode `preLaunchTask` for a debug launch of the server
/// binary. The server is expected to read `STATIC_DIR` on boot; the launch
/// config sets that to the printed path (or to the deterministic
/// `<install_root>/<frontend>` location).
///
/// Side-effect: any process listening on the server's port is killed
/// first. This frees the file lock on `target/debug/<server>.exe` on
/// Windows so the subsequent cargo debug build can replace the binary.
///
/// If the server exists but no frontend declares `serves = "<server>"`,
/// the port is still freed and the command succeeds without building.
pub fn cmd_prepare(
    cfg: &Config,
    root: &Path,
    server_name: &str,
) -> Result<(), String> {
    let server = cfg.server(server_name).ok_or_else(|| {
        format!("no [[server]] named `{server_name}` in viewer-ctl.toml")
    })?;

    // Free the port so the cargo debug build can replace the running binary
    // (Windows holds a file lock on the .exe of any running process).
    // cmd_stop is idempotent: it succeeds silently if nothing is listening.
    server::cmd_stop(cfg, &server.name)?;

    // Belt-and-braces: also kill any orphaned process whose image name matches
    // the server's package (e.g. a previous lldb debug session that exited
    // ungracefully and left the binary running on a stale or no port).
    // Without this the next `cargo build` fails with
    // "failed to remove file ... Access denied" on Windows.
    let orphans = pids_by_image_name(&server.package);
    if !orphans.is_empty() {
        warn!(
            "prepare",
            "killing {} orphaned `{}` process(es): {:?}",
            orphans.len(),
            server.package,
            orphans.iter().map(|p| p.as_u32()).collect::<Vec<_>>()
        );
        for pid in &orphans {
            kill_process(*pid, "prepare");
        }
    }

    let Some(fe) = cfg.frontend_for_server(&server.name) else {
        info!(
            "prepare",
            "server `{}` has no linked frontend; nothing to build", server.name
        );
        return Ok(());
    };
    build_frontend(root, fe)?;
    install_frontend(cfg, root, fe)?;
    let install = cfg.frontend_install_dir(&fe.name);
    println!("{}", disp(&install));
    Ok(())
}

/// Print the resolved STATIC_DIR for a server's linked frontend.
///
/// Errors if the server is unknown or has no linked frontend. Does not
/// build or install.
pub fn cmd_static_dir(
    cfg: &Config,
    server_name: &str,
) -> Result<(), String> {
    let server = cfg.server(server_name).ok_or_else(|| {
        format!("no [[server]] named `{server_name}` in viewer-ctl.toml")
    })?;
    let fe = cfg.frontend_for_server(&server.name).ok_or_else(|| {
        format!(
            "server `{}` has no linked frontend in viewer-ctl.toml",
            server.name
        )
    })?;
    let install = cfg.frontend_install_dir(&fe.name);
    println!("{}", disp(&install));
    Ok(())
}

//! Server lifecycle: build, install, start, stop (ported from viewer-ctl).

use std::{
    env,
    fs,
    io::Write,
    net::TcpStream,
    path::Path,
    process::{
        Command,
        Stdio,
    },
    time::{
        Duration,
        Instant,
    },
};

use crate::{
    config::{
        Config,
        Server,
    },
    error,
    info,
    paths::{
        crate_manifest_path_str,
        disp,
    },
    process::{
        kill_process,
        pids_by_image_name,
        pids_on_port,
        print_process_info,
    },
    shell::{
        run_cmd_args,
        which,
    },
    warn,
};

pub fn build_server(
    root: &Path,
    s: &Server,
) -> Result<(), String> {
    let tag = s.name.as_str();
    let crate_path = root.join(&s.source_dir);
    let manifest = crate_manifest_path_str(&crate_path)?;
    info!(tag, "cargo build --release in {}", disp(&crate_path));
    run_cmd_args(
        "cargo",
        &["build", "--release", "--manifest-path", manifest.as_str()],
        root,
        tag,
    )
}

pub fn install_server(
    root: &Path,
    s: &Server,
) -> Result<(), String> {
    let tag = s.name.as_str();

    // Determine the binary name: on Windows the release binary has an .exe suffix.
    let bin_name = if cfg!(target_os = "windows") {
        format!("{}.exe", s.package)
    } else {
        s.package.clone()
    };

    // Look for a pre-built release binary in the workspace target directory.
    // This avoids rebuilding from source when `build_server` / `trunk build`
    // was already run — and also avoids the mixed-separator issues that arise
    // from passing a Windows Path to `cargo install --path`.
    let release_bin = root.join("target").join("release").join(&bin_name);

    if release_bin.exists() {
        // Install by copying the binary to ~/.cargo/bin/.
        let cargo_home = std::env::var_os("CARGO_HOME")
            .map(std::path::PathBuf::from)
            .or_else(|| dirs::home_dir().map(|h| h.join(".cargo")))
            .ok_or_else(|| {
                "cannot locate cargo home (CARGO_HOME not set and HOME unknown)"
                    .to_string()
            })?;
        let dest = cargo_home.join("bin").join(&bin_name);
        info!(
            tag,
            "installing pre-built binary {} → {}",
            disp(&release_bin),
            disp(&dest)
        );
        fs::copy(&release_bin, &dest)
            .map_err(|e| format!("failed to copy binary: {e}"))?;
        Ok(())
    } else {
        // No pre-built binary found — fall back to building from source.
        // Run from the crate directory and install `--path .` so Cargo sees a
        // valid package path on every platform.
        let crate_path = root.join(&s.source_dir);
        info!(
            tag,
            "no pre-built binary found; building via cargo install --path . from {}",
            disp(&crate_path)
        );
        run_cmd_args(
            "cargo",
            &["install", "--path", ".", "--force"],
            &crate_path,
            tag,
        )
    }
}

pub fn cmd_start(
    cfg: &Config,
    root: &Path,
    server: &str,
    foreground: bool,
    extra: Vec<String>,
) -> Result<(), String> {
    let s = cfg.server(server).ok_or_else(|| {
        format!("no [[server]] named `{server}` in viewer-ctl.toml")
    })?;
    let tag = s.name.as_str();
    let port = port_for(s);

    // Step 1: ensure port is free.
    info!(tag, "checking port {port} for existing instances...");
    let listeners = pids_on_port(port);
    if !listeners.is_empty() {
        warn!(
            tag,
            "port {port} in use by PID(s): {:?}",
            listeners.iter().map(|p| p.as_u32()).collect::<Vec<_>>()
        );
        for pid in &listeners {
            kill_process(*pid, tag);
        }
        std::thread::sleep(Duration::from_secs(1));
        let remaining = pids_on_port(port);
        if !remaining.is_empty() {
            return Err(format!(
                "port {port} still occupied by {:?} — aborting",
                remaining.iter().map(|p| p.as_u32()).collect::<Vec<_>>()
            ));
        }
        info!(tag, "port {port} freed.");
    }

    // Step 2: locate the binary; auto-install on first run.
    let bin_path = match which(&s.package) {
        Ok(p) => p,
        Err(_) => {
            info!(
                tag,
                "{} not found on PATH — installing from source...", s.package
            );
            install_server(root, s)?;
            which(&s.package).map_err(|_| {
                format!(
                    "installed {} but still not found on PATH — check ~/.cargo/bin is in PATH",
                    s.package
                )
            })?
        },
    };

    // Step 3: derive STATIC_DIR from linked frontend if installed.
    let mut env_vars: Vec<(String, String)> =
        s.env.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
    if let Some(fe) = cfg.frontend_for_server(&s.name) {
        let install_dir = cfg.frontend_install_dir(&fe.name);
        if install_dir.is_dir() {
            info!(tag, "STATIC_DIR={}", disp(&install_dir));
            env_vars.push((
                "STATIC_DIR".into(),
                install_dir.to_string_lossy().into_owned(),
            ));
        } else {
            warn!(
                tag,
                "frontend `{}` not installed (no {}); server will use its built-in default",
                fe.name,
                disp(&install_dir)
            );
        }
    }
    env_vars.push(("PORT".into(), port.to_string()));

    // Step 4: assemble args and launch.
    let mut server_args: Vec<String> = s.start_args.clone();
    server_args.extend(extra);

    info!(tag, "starting {} on port {port}", disp(&bin_path));

    if foreground {
        info!(
            tag,
            "foreground mode: stdout/stderr inherited; blocking until exit."
        );
        run_server_foreground(&bin_path, &server_args, &env_vars, root, tag)
    } else {
        spawn_server(&bin_path, &server_args, &env_vars, root, tag)?;

        // Wait for the server to actually bind the port so callers (VS Code
        // `serverReadyAction`, scripts, etc.) can rely on the URL being live
        // when this process exits. Print a single, stable line that downstream
        // pattern matchers can latch onto:
        //     Listening on http://localhost:<port>
        wait_for_port_ready(port, Duration::from_secs(15), tag);
        println!("Listening on http://localhost:{port}");
        // Explicitly flush stdout so piped consumers (tail, grep, etc.) see the
        // sentinel line before viewer-ctl exits.
        let _ = std::io::stdout().flush();
        Ok(())
    }
}

/// Poll TCP connect to localhost:port until success or timeout.
///
/// Logs a warning on timeout but does not fail — the server may still come
/// up later, and the caller can decide what to do. We only block start()
/// long enough to make `serverReadyAction` reliable.
fn wait_for_port_ready(
    port: u16,
    timeout: Duration,
    tag: &str,
) {
    let deadline = Instant::now() + timeout;
    let addr = format!("127.0.0.1:{port}");
    while Instant::now() < deadline {
        if TcpStream::connect_timeout(
            &addr.parse().expect("valid socket addr"),
            Duration::from_millis(200),
        )
        .is_ok()
        {
            info!(tag, "port {port} is accepting connections.");
            return;
        }
        std::thread::sleep(Duration::from_millis(150));
    }
    warn!(
        tag,
        "timed out waiting for port {port} to become ready after {:?}", timeout
    );
}

pub fn cmd_stop(
    cfg: &Config,
    server: &str,
) -> Result<(), String> {
    let s = cfg.server(server).ok_or_else(|| {
        format!("no [[server]] named `{server}` in viewer-ctl.toml")
    })?;
    let tag = s.name.as_str();
    let port = port_for(s);

    // ── Phase 1: kill any process listening on the server port ────────────
    info!(tag, "looking for {} on port {port}...", s.package);
    let pids = pids_on_port(port);
    if pids.is_empty() {
        info!(tag, "no process listening on port {port}.");
    }
    for pid in &pids {
        warn!(tag, "found process on port {port}:");
        print_process_info(*pid, tag);
        if kill_process(*pid, tag) {
            info!(tag, "PID {} terminated.", pid.as_u32());
        } else {
            error!(tag, "could not terminate PID {}.", pid.as_u32());
            if cfg!(windows) {
                error!(tag, "  taskkill /F /PID {}", pid.as_u32());
            }
            error!(tag, "  kill -9 {}", pid.as_u32());
            return Err(format!("failed to kill PID {}", pid.as_u32()));
        }
    }

    // ── Phase 2: kill any orphaned processes by image name ─────────────────
    // Processes that crashed before binding (or were launched from a different
    // path like target/release/) won't appear in the port scan above, but they
    // still hold file locks that prevent `install` from copying a new binary.
    let zombies: Vec<_> = pids_by_image_name(&s.package)
        .into_iter()
        .filter(|pid| !pids.contains(pid))
        .collect();
    if !zombies.is_empty() {
        warn!(
            tag,
            "found {} orphaned {} process(es) not on port {port} — cleaning up",
            zombies.len(),
            s.package
        );
        for pid in zombies {
            print_process_info(pid, tag);
            if kill_process(pid, tag) {
                info!(tag, "orphan PID {} terminated.", pid.as_u32());
            } else {
                error!(tag, "could not terminate orphan PID {}.", pid.as_u32());
            }
        }
    }

    Ok(())
}

fn port_for(s: &Server) -> u16 {
    env::var("PORT")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(s.port)
}

/// Run the server in the foreground: inherit stdout/stderr from the current
/// process and block until the child exits. The caller's terminal sees all
/// server output directly. Returns an error if the process exits with a
/// non-zero status.
fn run_server_foreground(
    bin_path: &Path,
    args: &[String],
    env_vars: &[(String, String)],
    cwd: &Path,
    tag: &str,
) -> Result<(), String> {
    let mut cmd = Command::new(bin_path);
    for (k, v) in env_vars {
        cmd.env(k, v);
    }
    cmd.args(args)
        .current_dir(cwd)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    let mut child = cmd
        .spawn()
        .map_err(|e| format!("failed to launch {}: {e}", disp(bin_path)))?;

    info!(
        tag,
        "running in foreground (PID {}). Press Ctrl-C to stop.",
        child.id()
    );

    let status = child
        .wait()
        .map_err(|e| format!("error waiting for {}: {e}", disp(bin_path)))?;

    if status.success() {
        info!(tag, "process exited successfully.");
        Ok(())
    } else {
        Err(format!("{} exited with status: {}", disp(bin_path), status))
    }
}

fn spawn_server(
    bin_path: &Path,
    args: &[String],
    env_vars: &[(String, String)],
    cwd: &Path,
    tag: &str,
) -> Result<(), String> {
    // Spawn the server detached so viewer-ctl can exit cleanly.
    // Using exec() on Unix would replace the viewer-ctl process with the
    // server, which means wait_for_port_ready and the "Listening on..."
    // sentinel message would never be reached, causing piped consumers
    // (tail, grep, VS Code serverReadyAction) to hang indefinitely.
    let mut cmd = Command::new(bin_path);
    for (k, v) in env_vars {
        cmd.env(k, v);
    }
    cmd.args(args)
        .current_dir(cwd)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());

    // On Unix, move the child into a new process group so it is not
    // killed by SIGHUP when the terminal/parent session closes.
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }

    // On Windows the shell creates the pipe with bInheritHandle=TRUE, so
    // every child spawned via CreateProcess(bInheritHandles=TRUE) inherits
    // the write-end of the pipe even though we redirect the child's own
    // stdout/stderr to NUL.  The child then keeps the pipe alive after
    // viewer-ctl exits, and `tail` never sees EOF.
    //
    // Fix: mark the parent's stdout and stderr handles as non-inheritable
    // right before we spawn, so the child receives no reference to the pipe.
    #[cfg(windows)]
    {
        use windows_sys::Win32::{
            Foundation::HANDLE_FLAG_INHERIT,
            System::Console::{
                GetStdHandle,
                STD_ERROR_HANDLE,
                STD_OUTPUT_HANDLE,
            },
        };
        unsafe {
            for handle_id in [STD_OUTPUT_HANDLE, STD_ERROR_HANDLE] {
                let h = GetStdHandle(handle_id);
                if !h.is_null()
                    && h != windows_sys::Win32::Foundation::INVALID_HANDLE_VALUE
                {
                    windows_sys::Win32::Foundation::SetHandleInformation(
                        h,
                        HANDLE_FLAG_INHERIT,
                        0,
                    );
                }
            }
        }
    }

    cmd.spawn()
        .map_err(|e| format!("failed to launch {}: {e}", disp(bin_path)))?;
    info!(tag, "launched (detached). viewer-ctl exiting.");
    Ok(())
}

//! Frontend lifecycle: build (with optional prebuild steps) and install
//! (ported from viewer-ctl).

use std::{
    fs,
    path::Path,
};

use crate::{
    config::{
        Config,
        Frontend,
        PrebuildStep,
    },
    info,
    paths::{
        copy_dir_contents,
        disp,
    },
    shell::run_cmd_owned,
};

pub fn build_frontend(
    root: &Path,
    f: &Frontend,
) -> Result<(), String> {
    let tag = f.name.as_str();
    let source = root.join(&f.source_dir);
    if !source.is_dir() {
        return Err(format!("frontend source not found: {}", disp(&source)));
    }

    // Run prebuild steps (e.g. npm install).
    for step in &f.prebuild {
        let dir = root.join(&step.dir);
        if !should_run_prebuild(&dir, step) {
            info!(tag, "prebuild skipped ({}): condition not met", step.dir);
            continue;
        }
        info!(tag, "prebuild {} in {}", step.cmd.join(" "), disp(&dir));
        run_cmd_owned(&step.cmd, &dir, tag)?;
    }

    info!(
        tag,
        "build: {} (cwd={})",
        f.build_cmd.join(" "),
        disp(&source)
    );
    run_cmd_owned(&f.build_cmd, &source, tag)?;

    let output = root.join(&f.build_output);
    if !output.join("index.html").exists() {
        return Err(format!(
            "build did not produce {}/index.html",
            disp(&output)
        ));
    }

    // Copy extra assets (e.g. public/) into build_output so the install step
    // sees a single self-contained dir.
    for asset_dir in &f.extra_assets {
        let dir = root.join(asset_dir);
        if dir.is_dir() {
            copy_dir_contents(&dir, &output, tag)?;
        }
    }
    info!(tag, "frontend built → {}", disp(&output));
    Ok(())
}

pub fn install_frontend(
    cfg: &Config,
    root: &Path,
    f: &Frontend,
) -> Result<(), String> {
    let tag = f.name.as_str();
    let output = root.join(&f.build_output);
    if !output.join("index.html").exists() {
        return Err(format!(
            "build output not found at {} — run `install-ctl viewer build {}` first",
            disp(&output),
            f.name
        ));
    }
    let dest = cfg.frontend_install_dir(&f.name);
    info!(tag, "installing to {}", disp(&dest));

    // Wipe the existing install dir, then mirror build_output into it. Done
    // in two steps so stale files from previous builds (e.g. old hashed
    // wasm/js bundles) don't linger and confuse the running server.
    if dest.exists() {
        fs::remove_dir_all(&dest)
            .map_err(|e| format!("failed to clear {}: {e}", disp(&dest)))?;
    }
    fs::create_dir_all(&dest)
        .map_err(|e| format!("failed to create {}: {e}", disp(&dest)))?;
    copy_dir_contents(&output, &dest, tag)?;

    info!(tag, "frontend installed.");
    Ok(())
}

fn should_run_prebuild(
    dir: &Path,
    step: &PrebuildStep,
) -> bool {
    let Some(cond) = &step.condition else {
        return true;
    };
    if let Some(rel) = cond.strip_prefix("missing:") {
        return !dir.join(rel).exists();
    }
    // Unknown condition → run anyway (fail safe).
    true
}

//! Extension lifecycle (ported from viewer-ctl). Currently only the VS Code
//! installer kind is wired up.

use std::{
    env,
    fs,
    path::{
        Path,
        PathBuf,
    },
};

use crate::{
    config::{
        Config,
        Extension,
    },
    info,
    paths::{
        copy_dir_contents,
        disp,
    },
    shell::{
        run_cmd_args,
        run_cmd_owned,
    },
};

pub fn build_extension(
    root: &Path,
    e: &Extension,
) -> Result<(), String> {
    let tag = e.name.as_str();
    let dir = root.join(&e.source_dir);
    info!(tag, "build: {} (cwd={})", e.build_cmd.join(" "), disp(&dir));
    run_cmd_owned(&e.build_cmd, &dir, tag)
}

pub fn install_extension(
    _cfg: &Config,
    root: &Path,
    e: &Extension,
) -> Result<(), String> {
    // Build first so out/ is fresh.
    build_extension(root, e)?;
    match e.kind.as_str() {
        "vscode" => install_vscode_extension(root, e),
        other => Err(format!(
            "unknown extension kind `{other}` — install-ctl only knows `vscode`"
        )),
    }
}

#[derive(serde::Deserialize)]
struct PkgJson {
    publisher: Option<String>,
    name: String,
    version: String,
}

fn install_vscode_extension(
    root: &Path,
    e: &Extension,
) -> Result<(), String> {
    let tag = e.name.as_str();
    let ext_dir = root.join(&e.source_dir);

    let pkg_path = ext_dir.join(&e.package_json);
    let pkg_text = fs::read_to_string(&pkg_path)
        .map_err(|err| format!("failed to read {}: {err}", disp(&pkg_path)))?;
    let pkg: PkgJson = serde_json::from_str(&pkg_text)
        .map_err(|err| format!("failed to parse {}: {err}", disp(&pkg_path)))?;
    let publisher = pkg.publisher.as_deref().unwrap_or("undefined_publisher");
    let dirname = format!("{}.{}-{}", publisher, pkg.name, pkg.version);

    let user_home = env::var("USERPROFILE")
        .or_else(|_| env::var("HOME"))
        .map_err(|_| "neither USERPROFILE nor HOME is set".to_string())?;
    let install_dir = PathBuf::from(&user_home)
        .join(".vscode")
        .join("extensions")
        .join(&dirname);

    info!(tag, "install dir: {}", disp(&install_dir));

    if install_dir.is_dir() {
        // Fast path: in-place sync.
        info!(tag, "extension dir exists — syncing in-place...");

        let out_dst = install_dir.join("out");
        let _ = fs::remove_dir_all(&out_dst);
        fs::create_dir_all(&out_dst).map_err(|err| err.to_string())?;
        copy_dir_contents(&ext_dir.join("out"), &out_dst, tag)?;

        let res_src = ext_dir.join("resources");
        if res_src.is_dir() {
            let res_dst = install_dir.join("resources");
            fs::create_dir_all(&res_dst).map_err(|err| err.to_string())?;
            copy_dir_contents(&res_src, &res_dst, tag)?;
        }

        fs::copy(&pkg_path, install_dir.join(&e.package_json))
            .map_err(|err| format!("failed to copy package.json: {err}"))?;

        let nm = ext_dir.join("node_modules");
        if nm.is_dir() {
            let nm_dst = install_dir.join("node_modules");
            fs::create_dir_all(&nm_dst).map_err(|err| err.to_string())?;
            copy_dir_contents(&nm, &nm_dst, tag)?;
        }

        info!(tag, "sync complete. Reload the VS Code window to activate.");
    } else {
        // Slow path: package + install via vsce + code.
        info!(tag, "first-time install — packaging VSIX...");
        run_cmd_args(
            "vsce",
            &[
                "package",
                "--no-dependencies",
                "--allow-missing-repository",
                "--skip-license",
            ],
            &ext_dir,
            tag,
        )?;
        let vsix = find_newest_vsix(&ext_dir)?;
        info!(tag, "installing {}...", disp(&vsix));
        run_cmd_args(
            "code",
            &[
                "--install-extension",
                vsix.to_str().unwrap_or(""),
                "--force",
            ],
            &ext_dir,
            tag,
        )?;
        info!(tag, "done. Reload the VS Code window to activate.");
    }
    Ok(())
}

fn find_newest_vsix(dir: &Path) -> Result<PathBuf, String> {
    let mut vsix: Vec<_> = fs::read_dir(dir)
        .map_err(|e| e.to_string())?
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().map(|x| x == "vsix").unwrap_or(false))
        .collect();
    vsix.sort_by_key(|e| {
        e.metadata()
            .and_then(|m| m.modified())
            .unwrap_or(std::time::SystemTime::UNIX_EPOCH)
    });
    vsix.last()
        .map(|e| e.path())
        .ok_or_else(|| "no .vsix file found in extension dir".to_string())
}

//! Multi-step task runner (ported from viewer-ctl).

use std::path::Path;

use crate::{
    config::Config,
    info,
    paths::disp,
    shell::run_cmd_owned,
    warn,
};

pub fn cmd_task(
    cfg: &Config,
    root: &Path,
    name: &str,
) -> Result<(), String> {
    let task = cfg.task(name).ok_or_else(|| {
        format!("no [[task]] named `{name}` in viewer-ctl.toml")
    })?;
    let tag = task.name.as_str();
    if !task.description.is_empty() {
        info!(tag, "{}", task.description);
    }
    for step in &task.steps {
        let dir = root.join(&step.dir);
        info!(tag, "step: {} (cwd={})", step.cmd.join(" "), disp(&dir));
        let res = run_cmd_owned(&step.cmd, &dir, tag);
        if let Err(e) = res {
            if step.allow_failure {
                warn!(tag, "step failed (allow_failure=true): {e}");
            } else {
                return Err(e);
            }
        }
    }
    info!(tag, "done.");
    Ok(())
}

